// Fixture corruption deliberately uses a separate, unbounded connection to an
// explicit temporary database. The production connection must reject it before
// Scan copies oversized values, including values generated by computed views.
func corruptSQL(t *testing.T, dir, statement string) {
	t.Helper()
	u := url.URL{Scheme: "file", Path: filepath.Join(dir, persistentDB)}
	db, err := sql.Open("sqlite", u.String())
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	if _, err := db.Exec(statement); err != nil {
		t.Fatal(err)
	}
}

func boundedCorrupt(t *testing.T, operation func() error) {
	t.Helper()
	// Tests are deliberately not parallel: TotalAlloc is process-wide. Fixture
	// construction (which can legitimately write 64 MiB) is outside this window.
	runtime.GC()
	var before, after runtime.MemStats
	runtime.ReadMemStats(&before)
	err := operation()
	runtime.ReadMemStats(&after)
	wantKind(t, err, ErrCorrupt)
	allocated := after.TotalAlloc - before.TotalAlloc
	t.Logf("corrupt result rejected with %d Go bytes allocated", allocated)
	if allocated >= 2*1024*1024 {
		t.Fatalf("oversized result allocated %d bytes (limit <2 MiB)", allocated)
	}
}

func configuredLimit(t *testing.T, s *Persistent) {
	t.Helper()
	conn, err := s.db.Conn(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	defer conn.Close()
	actual, err := sqlite.Limit(conn, sqlite3.SQLITE_LIMIT_LENGTH, -1)
	if err != nil || actual != persistentSQLMaxLength {
		t.Fatalf("connection limit=%d err=%v", actual, err)
	}
}

func replaceWithUnboundedConnection(t *testing.T, s *Persistent) {
	t.Helper()
	conn, err := s.db.Conn(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	var old any
	err = conn.Raw(func(dc any) error { old = dc; return driver.ErrBadConn })
	if !errors.Is(err, driver.ErrBadConn) {
		t.Fatalf("failed to discard driver connection: %v", err)
	}
	conn.Close() // Raw(ErrBadConn) already discarded this underlying connection.
	fresh, err := s.db.Conn(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	defer fresh.Close()
	if err := fresh.Raw(func(dc any) error {
		if old == dc {
			t.Fatal("underlying driver connection was not replaced")
		}
		return nil
	}); err != nil {
		t.Fatal(err)
	}
	actual, err := sqlite.Limit(fresh, sqlite3.SQLITE_LIMIT_LENGTH, -1)
	if err != nil || actual <= persistentSQLMaxLength {
		t.Fatalf("replacement not genuinely unbounded: limit=%d err=%v", actual, err)
	}
	// Return it to the pool WITHOUT installing the limit: the next actual store
	// operation must configure this replacement itself, not a throwaway handle.
}

func TestPersistentOversizedResultAllocationsAndReplacement(t *testing.T) {
	cases := []struct{ name, statement string }{
		{"ordinary-value", "UPDATE secrets SET value=zeroblob(67108864)"},
		{"computed-value", "ALTER TABLE secrets RENAME TO saved_secrets; CREATE VIEW secrets AS SELECT lookup,zeroblob(67108864) AS value FROM saved_secrets"},
		{"ordinary-keycheck", "UPDATE metadata SET keycheck=zeroblob(67108864)"},
		{"computed-keycheck", "ALTER TABLE metadata RENAME TO saved_metadata; CREATE VIEW metadata AS SELECT id,version,profile,zeroblob(67108864) AS keycheck FROM saved_metadata"},
		{"ordinary-profile", "UPDATE metadata SET profile=CAST(zeroblob(67108864) AS TEXT)"},
		{"computed-profile", "ALTER TABLE metadata RENAME TO saved_metadata; CREATE VIEW metadata AS SELECT id,version,CAST(zeroblob(67108864) AS TEXT) AS profile,keycheck FROM saved_metadata"},
		{"computed-version", "ALTER TABLE metadata RENAME TO saved_metadata; CREATE VIEW metadata AS SELECT id,zeroblob(67108864) AS version,profile,keycheck FROM saved_metadata"},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			dir := privateTempDir(t)
			v := &fakeVault{}
			s := testOpen(t, dir, v)
			configuredLimit(t, s) // Bootstrap initialized on a bounded connection too.
			mustSet(t, s, "record", "complete")
			corruptSQL(t, dir, tc.statement)
			get := func() error { _, err := s.Get("record"); return err }
			boundedCorrupt(t, get)
			replaceWithUnboundedConnection(t, s)
			boundedCorrupt(t, get)
			configuredLimit(t, s)
			if strings.Contains(tc.name, "profile") || strings.Contains(tc.name, "keycheck") || strings.Contains(tc.name, "version") {
				// Write-side metadata verification must also stay on its bounded
				// transaction connection, including after driver replacement.
				replaceWithUnboundedConnection(t, s)
				boundedCorrupt(t, func() error { return s.Set("record", "new") })
				configuredLimit(t, s)
				replaceWithUnboundedConnection(t, s)
				boundedCorrupt(t, func() error { return s.Delete("record") })
				configuredLimit(t, s)
				s.Close()
				boundedCorrupt(t, func() error {
					opened, err := OpenPersistent(context.Background(), Options{Dir: dir, Vault: v})
					if opened != nil {
						opened.Close()
					}
					return err
				})
			}
		})
	}
}

func TestPersistentMalformedResultTypesAndExactMetadata(t *testing.T) {
	for _, tc := range []struct{ name, version, profile, keycheck string }{
		{"text-version", "CAST(version AS TEXT)", "profile", "keycheck"},
		{"real-version", "CAST(version AS REAL)", "profile", "keycheck"},
		{"null-version", "NULL", "profile", "keycheck"},
		{"blob-profile", "version", "CAST(profile AS BLOB)", "keycheck"},
		{"short-profile", "version", "substr(profile,1,35)", "keycheck"},
		{"long-profile", "version", "profile||'x'", "keycheck"},
		{"nul-profile", "version", "CAST(zeroblob(36) AS TEXT)", "keycheck"},
		{"text-keycheck", "version", "profile", "CAST(keycheck AS TEXT)"},
		{"short-keycheck", "version", "profile", "substr(keycheck,1,length(keycheck)-1)"},
		{"long-keycheck", "version", "profile", "CAST(keycheck||x'00' AS BLOB)"},
		{"integer-keycheck", "version", "profile", "1"},
		{"null-keycheck", "version", "profile", "NULL"},
	} {
		t.Run(tc.name, func(t *testing.T) {
			dir := privateTempDir(t)
			v := &fakeVault{}
			s := testOpen(t, dir, v)
			mustSet(t, s, "record", "complete")
			corruptSQL(t, dir, "ALTER TABLE metadata RENAME TO saved_metadata; CREATE VIEW metadata AS SELECT id,"+tc.version+" AS version,"+tc.profile+" AS profile,"+tc.keycheck+" AS keycheck FROM saved_metadata")
			_, err := s.Get("record")
			wantKind(t, err, ErrCorrupt)
			wantKind(t, s.Set("record", "new"), ErrCorrupt)
			wantKind(t, s.Delete("record"), ErrCorrupt)
			s.Close()
			_, err = OpenPersistent(context.Background(), Options{Dir: dir, Vault: v})
			wantKind(t, err, ErrCorrupt)
		})
	}
	for _, value := range []string{"CAST(value AS TEXT)", "17", "NULL"} {
		t.Run("value-"+value, func(t *testing.T) {
			dir := privateTempDir(t)
			s := testOpen(t, dir, &fakeVault{})
			mustSet(t, s, "record", "complete")
			corruptSQL(t, dir, "ALTER TABLE secrets RENAME TO saved_secrets; CREATE VIEW secrets AS SELECT lookup,"+value+" AS value FROM saved_secrets")
			_, err := s.Get("record")
			wantKind(t, err, ErrCorrupt)
		})
	}
}

func TestPersistentSQLiteLengthLimitCategory(t *testing.T) {
	s := testOpen(t, privateTempDir(t), &fakeVault{})
	conn, err := s.boundedConn(context.Background())
	if err != nil {
		t.Fatal(err)
	}
	defer conn.Close()
	var blob []byte
	err = conn.QueryRowContext(context.Background(), "SELECT zeroblob(67108864)").Scan(&blob)
	var coded interface{ Code() int }
	if !errors.As(err, &coded) || coded.Code()&255 != sqlite3.SQLITE_TOOBIG {
		t.Fatalf("expected driver TOOBIG before materialization: %v", err)
	}
	if len(blob) != 0 {
		t.Fatal("oversized result materialized")
	}
	wantKind(t, dbError("get", context.Background(), err), ErrCorrupt)
}

func TestPersistentConnectionLimitAllowsMaximumBinaryAndUnicode(t *testing.T) {
	dir := privateTempDir(t)
	v := &fakeVault{}
	s := testOpen(t, dir, v)
	values := []string{
		string(bytes.Repeat([]byte{0x00, 0xff, 0xc3, 0x28}, MaxPersistentValueBytes/4)),
		strings.Repeat("\U00010400", MaxPersistentValueBytes/4),
	}
	for i, value := range values {
		if len(value) != MaxPersistentValueBytes {
			t.Fatal("invalid max-size fixture")
		}
		replaceWithUnboundedConnection(t, s)
		name := []string{"binary", "unicode"}[i]
		mustSet(t, s, name, value)
		configuredLimit(t, s)
		replaceWithUnboundedConnection(t, s)
		wantGet(t, s, name, value)
		configuredLimit(t, s)
	}
	s.Close()
	s = testOpen(t, dir, v)
	wantGet(t, s, "binary", values[0])
	wantGet(t, s, "unicode", values[1])
}
